-- theme.lua — this machine's colors for Lua configs: Hyprland (hyprland.lua, liquid.lua) and nvim.
-- Generated by theme/retheme for {{theme.host}} ({{theme.palette}}, {{theme.variation}}): edit
-- theme/ and run retheme, not this file.
--
-- Every slot and token is a field, the same names the shell's Theme.qml uses: t.yellow, t.accent,
-- t.focus_accent. Each is bare hex, with the opacity appended for a translucent token. rgba() puts
-- one in Hyprland's syntax, optionally at another opacity, 0 to 1:
--     t.rgba(t.accent)         --> "rgba(E6C384ff)"
--     t.rgba(t.line, 0.533)    --> "rgba(54546D88)"

local t = {
    -- Slots: the palette's colors, by the names every palette shares.
{% for c in slots %}
    {{c.name|pad:15}} = "{{c|bare}}",{{col:39}}-- {{c|ref}}
{% endfor %}

    -- Tokens: the job each color does.
{% for c in ui %}
    {{c.name|pad:15}} = "{{c|hexa}}",{{col:39}}-- {{c|src}}
{% endfor %}

    -- Chrome roles, shared with kitty and waybar.
{% for c in roles %}
    {{c.name|pad:15}} = "{{c|hexa}}",{{col:39}}-- {{c|src}}
{% endfor %}
}

function t.rgba(hex, alpha)
    -- A misspelled name arrives as nil. Hand Hyprland a color it rejects, so it flags that one
    -- line and goes on, rather than an error that stops the rest of the config loading.
    if type(hex) ~= "string" then return "rgba(" .. tostring(hex) .. ")" end
    local a = alpha and math.floor(alpha * 255 + 0.5) or tonumber(hex:sub(7, 8), 16) or 255
    return ("rgba(%s%02x)"):format(hex:sub(1, 6), a)
end

return t
